"""Error pages and request identifiers generated by the edge (sections 4.12 and 4.19)."""

from __future__ import annotations

import json
import re
import socket

from support.server import Server, text

ULID = re.compile(r"^[0-9A-HJKMNP-TV-Z]{26}$")


def test_every_response_carries_a_request_id(server: Server) -> None:
    first = server.get("/response/list")
    second = server.get("/response/list")
    ids = [first.header("X-Request-ID"), second.header("X-Request-ID")]
    assert all(value and ULID.match(value) for value in ids), ids
    assert ids[1] > ids[0], "identifiers must sort by time"


def test_the_application_sees_the_same_request_id(server: Server) -> None:
    response = server.get("/environ/get?key=muru.request_id")
    assert text(response) == f"value={response.header('X-Request-ID')}"


def test_application_error_page_is_plain_text_by_default(server: Server) -> None:
    response = server.get("/response/raise-first")
    assert response.status == 500
    assert response.header("Content-Type") == "text/plain; charset=utf-8"
    assert response.header("Cache-Control") == "no-store"
    body = response.body.decode()
    assert body.startswith("500 Internal Server Error\nreason: app_error\nrequest id: ")
    assert f"request id: {response.header('X-Request-ID')}" in body

    # Development mode shows the traceback.

    assert "RuntimeError: raise-first-boom" in body


def test_application_error_page_as_html(server: Server) -> None:
    response = server.get("/response/raise-first", headers={"Accept": "text/html,*/*;q=0.8"})
    assert response.status == 500
    assert response.header("Content-Type") == "text/html; charset=utf-8"
    body = response.body.decode()
    assert "<title>500 Internal Server Error</title>" in body
    assert "<dd>app_error</dd>" in body
    assert "raise-first-boom" in body
    assert "<pre>" in body


def test_application_error_page_as_problem_json(server: Server) -> None:
    response = server.get("/response/raise-first", headers={"Accept": "application/json"})
    assert response.status == 500
    assert response.header("Content-Type") == "application/problem+json"
    problem = json.loads(response.body)
    assert problem["status"] == 500
    assert problem["title"] == "Internal Server Error"
    assert problem["reason"] == "app_error"
    assert problem["request_id"] == response.header("X-Request-ID")
    assert "raise-first-boom" in problem["traceback"]


def test_edge_generated_error_is_negotiated_too(server: Server) -> None:
    with socket.create_connection(("127.0.0.1", server.port), timeout=10) as sock:
        sock.sendall(
            b"POST /input/read-all HTTP/1.1\r\nHost: t\r\nAccept: application/json\r\n"
            b"Content-Length: 99999999999\r\n\r\n"
        )
        data = b""

        while True:
            chunk = sock.recv(65536)
            if not chunk:
                break
            data += chunk

    head, _, body = data.partition(b"\r\n\r\n")
    assert head.startswith(b"HTTP/1.1 413")
    assert b"content-type: application/problem+json" in head.lower()
    assert b"x-request-id: " in head.lower()
    problem = json.loads(body)
    assert problem["reason"] == "body_too_large"
    assert problem["status"] == 413
    assert "traceback" not in problem
